<?= $this->extend('layouts/shell') ?>
<?= $this->setVar('entryScript', 'assets/js/shop/app.js') ?>
<?= $this->section('content') ?>
<div id="shop-app" v-cloak>
  <div v-if="loading" class="status-panel" role="status">Loading your Shop…</div>
  <div v-else>
    <div class="alert" :class="access.mode==='FULL'?'alert-success':'alert-warning'" role="status"><strong>{{ access.mode }}</strong> — {{ access.message }}</div>
    <nav class="phase-nav" aria-label="Shop settings"><button v-for="item in navigation" :key="item.id" class="btn" :class="page===item.id?'btn-primary':'btn-outline-primary'" @click="page=item.id">{{ item.label }}</button><a class="btn btn-outline-secondary" href="/logout">Sign out</a></nav>
    <section v-if="page==='home'" class="welcome-panel"><h1>Account home</h1><p>Your identity, Shop and access configuration are ready.</p></section>
    <section v-if="page==='staff'" class="workspace"><h1>Staff</h1><form class="responsive-form" @submit.prevent="createStaff"><label>Name<input v-model="staffForm.name" required class="form-control"></label><label>Email<input v-model="staffForm.email" type="email" required class="form-control"></label><label>Temporary password<input v-model="staffForm.password" type="password" minlength="12" required class="form-control"></label><button class="btn btn-primary" :disabled="busy">Create Staff</button></form><div v-if="!staff.length" class="empty-panel">No Staff accounts yet.</div><article v-for="member in staff" :key="member.id" class="record-card"><div><strong>{{member.username}}</strong><p>{{member.role}} · {{member.status}}</p></div><button v-if="member.role==='STAFF'" class="btn btn-outline-primary" @click="toggleStaff(member)">{{member.status==='ACTIVE'?'Deactivate':'Reactivate'}}</button><details v-if="member.role==='STAFF'"><summary>Permissions</summary><div class="permission-grid"><label v-for="code in permissionCodes" :key="code"><input type="checkbox" @change="permission(member,code,$event.target.checked)"> {{code}}</label></div></details></article></section>
    <section v-if="page==='settings'" class="workspace"><h1>Shop settings</h1><form class="responsive-form" @submit.prevent="saveSettings"><label v-for="field in settingFields" :key="field.key">{{field.label}}<input v-model="settings[field.key]" class="form-control" :type="field.type||'text'" :required="field.required"></label><button class="btn btn-primary" :disabled="busy||readOnly">Save settings</button></form></section>
    <section v-if="page==='branding'" class="workspace"><h1>Branding</h1><div class="brand-preview" :style="previewStyle"><strong>{{branding.brand_display_name}}</strong><span>{{branding.tagline}}</span></div><form class="responsive-form" @submit.prevent="saveBranding"><label v-for="field in brandFields" :key="field.key">{{field.label}}<input v-model="branding[field.key]" class="form-control" :type="field.colour?'color':'text'" required></label><button class="btn btn-primary" :disabled="busy||readOnly">Save branding</button></form><h2>Brand assets</h2><form @submit.prevent="uploadAsset"><label>Asset type<select v-model="assetType" class="form-select"><option v-for="type in assetTypes">{{type}}</option></select></label><label>Image<input ref="asset" type="file" accept="image/png,image/jpeg,image/webp,image/x-icon" class="form-control" required></label><button class="btn btn-primary" :disabled="busy||readOnly">Upload or replace</button></form><div class="record-grid"><article v-for="asset in assets" class="record-card"><strong>{{asset.asset_type}}</strong><span>{{asset.width_px}}×{{asset.height_px}}</span></article></div></section>
    <section v-if="page==='domains'" class="workspace"><h1>Domains</h1><article v-for="domain in domains" class="record-card"><div><strong>{{domain.hostname}}</strong><p>{{domain.domain_type}} · {{domain.verification_status}} · TLS {{domain.certificate_status||'pending'}}</p></div><span v-if="domain.is_primary" class="badge text-bg-success">Primary</span></article><form class="responsive-form" @submit.prevent="requestDomain"><label>Custom hostname<input v-model="hostname" class="form-control" placeholder="shop.example.com" required></label><button class="btn btn-primary" :disabled="busy||readOnly">Request verification</button></form><div v-if="dnsToken" class="alert alert-info">Create a DNS TXT record containing <code>{{dnsToken}}</code>. Status verification is performed by the platform.</div></section>
    <section v-if="page==='subscription'" class="workspace"><h1>Subscription and access</h1><dl class="detail-grid"><div><dt>Plan</dt><dd>{{subscription.entitlement?.plan_code_snapshot||'None'}}</dd></div><div><dt>Access</dt><dd>{{subscription.access?.mode}}</dd></div><div><dt>Starts</dt><dd>{{subscription.entitlement?.starts_at||'—'}}</dd></div><div><dt>Ends</dt><dd>{{subscription.entitlement?.ends_at||'—'}}</dd></div><div><dt>Staff allowance</dt><dd>{{subscription.active_staff}} / {{subscription.entitlement?.max_active_staff_snapshot||0}}</dd></div></dl></section>
    <div v-if="notice" class="toast-notice" role="status">{{notice}}</div><div v-if="error" class="alert alert-danger" role="alert">{{error}}</div>
  </div>
</div>
<?= $this->endSection() ?>
